#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    if(N==1){printf("1\n1 1\n");return 0;}
    vector<int>par(N+1);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){scanf("%d",&par[i]);ch[par[i]].push_back(i);}
    vector<int>lf(N+1),rg(N+1);
    vector<vector<int>>bags;
    vector<pair<int,int>>tedges;
    // For each node v, interfaceBag[v] is a bag containing {par[v], v, lf[v], rg[v]}
    vector<int>intf(N+1,-1);
    auto addBag=[&](vector<int>b)->int{
        sort(b.begin(),b.end());
        b.erase(unique(b.begin(),b.end()),b.end());
        bags.push_back(b);
        return (int)bags.size()-1;
    };
    auto link=[&](int a,int b){if(a>=0&&b>=0&&a!=b)tedges.push_back({a+1,b+1});};
    for(int v=N;v>=1;v--){
        if(ch[v].empty()){
            lf[v]=rg[v]=v;
            vector<int>bag;
            if(v!=1)bag.push_back(par[v]);
            bag.push_back(v);
            intf[v]=addBag(bag);
        } else {
            auto&C=ch[v];
            lf[v]=lf[C[0]]; rg[v]=rg[C.back()];
            int prev=-1;
            for(int i=0;i<(int)C.size();i++){
                int c=C[i];
                // bag with {par[v],v,c,lf[c],rg[c]}
                vector<int>bag;
                if(v!=1)bag.push_back(par[v]);
                bag.push_back(v);bag.push_back(c);bag.push_back(lf[c]);bag.push_back(rg[c]);
                int b1=addBag(bag);
                link(intf[c],b1);
                if(i>0){
                    // transition bag: {par[v],v,rg[C[i-1]],lf[c]}
                    vector<int>bag2;
                    if(v!=1)bag2.push_back(par[v]);
                    bag2.push_back(v);bag2.push_back(rg[C[i-1]]);bag2.push_back(lf[c]);
                    int b2=addBag(bag2);
                    link(prev,b2);
                    link(b2,b1);
                } else {
                    link(prev,b1);
                }
                prev=b1;
            }
            intf[v]=prev;
        }
    }
    // close the cycle: edge rg[1]--lf[1]
    vector<int>leaves;
    for(int i=1;i<=N;i++)if(ch[i].empty())leaves.push_back(i);
    if(leaves.size()>=2){
        int b=addBag({1,lf[1],rg[1]});
        link(intf[1],b);
    }
    int K=(int)bags.size();
    printf("%d\n",K);
    for(int i=0;i<K;i++){
        printf("%d",(int)bags[i].size());
        for(int x:bags[i])printf(" %d",x);
        printf("\n");
    }
    for(auto&[a,b]:tedges)printf("%d %d\n",a,b);
}
